/**
 * The git-sync plugin's settings card: toggle the master switch, set the GitHub
 * remote, branch, interval, and auto-create flag, and save them into the
 * `git-sync` settings namespace.
 * @module @deepseek-ai/dsh-client-ui-git-sync/GitSyncCard
 */

import { useState, type CSSProperties } from 'react'
import type { InjectFace, PropsLocale, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import type {} from '@deepseek-ai/dsh-client-ui-settings/client'
// Type-only: pulls the SlotMap merge that declares `settings.plugin.item`.
import type {} from '@deepseek-ai/dsh-client-ui-settings-plugins/client'
import type { GitSyncCardFace, GitSyncFieldState } from './git-sync-card.ts'
import { NS } from './locales.ts'

export type GitSyncCardProps =
  PropsRuntime<'settings.plugin.item'>
  & PropsLocale<typeof NS>
  & InjectFace<GitSyncCardFace>

const cardStyle: CSSProperties = {
  border: '1px solid rgba(128,128,128,0.25)',
  borderRadius: 8,
  margin: '8px 0',
  background: 'rgba(128,128,128,0.06)',
}
const headerStyle: CSSProperties = {
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'flex-start',
  gap: 4,
  width: '100%',
  padding: '10px 12px',
  border: 'none',
  background: 'transparent',
  color: 'inherit',
  font: 'inherit',
  textAlign: 'left',
  cursor: 'pointer',
}
const titleStyle: CSSProperties = { fontWeight: 600 }
const descStyle: CSSProperties = { fontSize: 12, opacity: 0.7 }
const pendingStyle: CSSProperties = { fontSize: 12, color: '#e5a93d' }
const bodyStyle: CSSProperties = { padding: '4px 12px 12px', display: 'flex', flexDirection: 'column', gap: 8 }
const rowStyle: CSSProperties = { display: 'flex', alignItems: 'center', gap: 8 }
const labelStyle: CSSProperties = { flex: '0 0 180px', fontSize: 13 }
const inputStyle: CSSProperties = {
  flex: 1,
  padding: '4px 8px',
  borderRadius: 6,
  border: '1px solid rgba(128,128,128,0.35)',
  background: 'rgba(0,0,0,0.15)',
  color: 'inherit',
  font: 'inherit',
}
const hintStyle: CSSProperties = { fontSize: 11, opacity: 0.6, marginLeft: 188 }
const footerStyle: CSSProperties = { display: 'flex', justifyContent: 'flex-end', gap: 8, marginTop: 4 }
const buttonStyle: CSSProperties = { padding: '5px 14px', borderRadius: 6, border: '1px solid rgba(128,128,128,0.35)', background: 'transparent', color: 'inherit', cursor: 'pointer' }
const saveButtonStyle: CSSProperties = { ...buttonStyle, background: 'rgba(79,140,255,0.85)', color: '#fff', border: 'none' }
const smallButtonStyle: CSSProperties = { ...buttonStyle, padding: '3px 10px', fontSize: 12 }
const loginButtonStyle: CSSProperties = { ...saveButtonStyle, padding: '3px 10px', fontSize: 12 }
const statusStyle: CSSProperties = { fontSize: 13, fontWeight: 600 }
const noteStyle: CSSProperties = { fontSize: 12, color: '#e05e5e' }

function TextField(props: { id: string; label: string; hint?: string; value: GitSyncFieldState; onEdit: (v: string) => void }) {
  return (
    <div>
      <div style={rowStyle}>
        <label style={labelStyle} htmlFor={props.id}>{props.label}</label>
        <input
          id={props.id}
          type="text"
          style={inputStyle}
          value={String(props.value.value)}
          onChange={event => { props.onEdit(event.currentTarget.value) }}
        />
      </div>
      {props.hint !== undefined ? <div style={hintStyle}>{props.hint}</div> : null}
    </div>
  )
}

function NumberField(props: { id: string; label: string; value: GitSyncFieldState; onEdit: (v: number | string) => void }) {
  return (
    <div style={rowStyle}>
      <label style={labelStyle} htmlFor={props.id}>{props.label}</label>
      <input
        id={props.id}
        type="text"
        inputMode="numeric"
        style={inputStyle}
        value={String(props.value.value)}
        onChange={event => {
          const text = event.currentTarget.value
          const parsed = Number(text)
          props.onEdit(Number.isFinite(parsed) && text.trim() !== '' ? parsed : text)
        }}
      />
    </div>
  )
}

function BoolField(props: { id: string; label: string; value: GitSyncFieldState; onEdit: (v: boolean) => void }) {
  return (
    <div style={rowStyle}>
      <label style={labelStyle} htmlFor={props.id}>{props.label}</label>
      <input
        id={props.id}
        type="checkbox"
        checked={props.value.value === true}
        onChange={event => { props.onEdit(event.currentTarget.checked) }}
      />
    </div>
  )
}

/**
 * Render the git-sync settings card.
 * @param props - locale copy, the card snapshot, and its form actions.
 * @returns the card, or nothing when the namespace is not served.
 */
export function GitSyncCard(props: GitSyncCardProps) {
  const { t } = props
  const state = props.useGitSyncCard(snapshot => snapshot)
  const [open, setOpen] = useState(false)
  if (!state.available) return null
  const disabled = !state.writable

  let statusText: string
  let statusColor = '#9aa2b1'
  switch (state.authStatus) {
    case 'logged-in':
      statusText = t('auth.status.logged-in')
      statusColor = '#3ecf8e'
      break
    case 'not-logged-in':
      statusText = t('auth.status.not-logged-in')
      statusColor = '#e05e5e'
      break
    case 'unknown':
      statusText = t('auth.status.unknown')
      break
    default:
      statusText = state.authStatus.startsWith('opening') ? t('auth.status.opening') : state.authStatus
      break
  }

  return (
    <li style={cardStyle}>
      <button
        type="button"
        style={headerStyle}
        aria-expanded={open}
        aria-label={`${t(open ? 'state.collapse' : 'state.expand')}: ${t('card.title')}`}
        onClick={() => { setOpen(!open) }}
      >
        <span style={titleStyle}>{t('card.title')}</span>
        <span style={descStyle}>{t('card.description')}</span>
        {state.dirty ? <span style={pendingStyle}>{t('state.unsaved')}</span> : null}
      </button>
      {open
        ? (
          <div style={bodyStyle}>
            {!state.writable ? <p style={noteStyle}>{t('state.readOnly')}</p> : null}
            <div style={rowStyle}>
              <span style={labelStyle}>{t('auth.status')}</span>
              <span style={{ ...statusStyle, color: statusColor }}>{statusText}</span>
              <button type="button" style={smallButtonStyle} onClick={props.refreshStatus}>{t('action.refreshStatus')}</button>
              <button type="button" style={loginButtonStyle} onClick={props.login}>{t('action.login')}</button>
            </div>
            <div style={hintStyle}>{t('auth.hint')}</div>
            <BoolField
              id="git-sync-enabled"
              label={t('field.enabled')}
              value={state.enabled}
              onEdit={value => { props.edit('enabled', value) }}
            />
            <TextField
              id="git-sync-remote"
              label={t('field.remoteUrl')}
              hint={t('field.remoteUrlHint')}
              value={state.remoteUrl}
              onEdit={value => { props.edit('remoteUrl', value) }}
            />
            <TextField
              id="git-sync-branch"
              label={t('field.branch')}
              value={state.branch}
              onEdit={value => { props.edit('branch', value) }}
            />
            <NumberField
              id="git-sync-interval"
              label={t('field.intervalMinutes')}
              value={state.intervalMinutes}
              onEdit={value => { props.edit('intervalMinutes', value) }}
            />
            <BoolField
              id="git-sync-autocreate"
              label={t('field.autoCreateRepo')}
              value={state.autoCreateRepo}
              onEdit={value => { props.edit('autoCreateRepo', value) }}
            />
            {state.failed ? <p style={noteStyle}>{t('state.saveFailed')}</p> : null}
            <div style={footerStyle}>
              <button
                type="button"
                style={buttonStyle}
                disabled={disabled || !state.dirty || state.saving}
                onClick={props.discard}
              >
                {t('action.discard')}
              </button>
              <button
                type="button"
                style={saveButtonStyle}
                disabled={disabled || !state.dirty || state.saving}
                onClick={props.save}
              >
                {t(state.saving ? 'action.saving' : 'action.save')}
              </button>
            </div>
          </div>
        )
        : null}
    </li>
  )
}

export type { SyncKey } from './locales.ts'

