/**
 * The git-sync settings card controller: stages edits over the `git-sync`
 * namespace scope and writes them on save. Self-contained (no dependency on the
 * ui-settings-plugins card internals): booleans render as checkboxes, text and
 * numbers as inputs.
 * @module @deepseek-ai/dsh-client-ui-git-sync/git-sync-card
 */

import type { SettingsScope } from '@deepseek-ai/dsh-client-runtime/client'
import { createSnapshotStore, type SnapshotStore } from '@deepseek-ai/dsh-client-runtime/client'

/** The settings namespace the host dsh-git-sync plugin registered. */
export const GIT_SYNC_NS = 'git-sync'

/** The editable slice of the git-sync settings section. */
export interface GitSyncSettings {
  enabled?: boolean
  remoteUrl?: string
  branch?: string
  intervalMinutes?: number
  autoCreateRepo?: boolean
  loginRequest?: number
  statusRequest?: number
  authStatus?: string
}

/** One control's rendered state. */
export interface GitSyncFieldState {
  value: boolean | string | number
  overridden: boolean
}

/** The card's full snapshot. */
export interface GitSyncCardState {
  available: boolean
  writable: boolean
  dirty: boolean
  saving: boolean
  failed: boolean
  authStatus: string
  enabled: GitSyncFieldState
  remoteUrl: GitSyncFieldState
  branch: GitSyncFieldState
  intervalMinutes: GitSyncFieldState
  autoCreateRepo: GitSyncFieldState
}

/** Write actions the card's slot entry injects. */
export interface GitSyncCardActions {
  edit: (field: string, value: boolean | string | number) => void
  save: () => void
  discard: () => void
  /** Ask the host to open the GitHub browser login. */
  login: () => void
  /** Ask the host to re-check the GitHub auth status. */
  refreshStatus: () => void
}

/** The registration-side face the card's slot entry injects. */
export interface GitSyncCardFace extends GitSyncCardActions {
  hooks: { gitSyncCard: SnapshotStore<GitSyncCardState> }
}

/** Bridges the `git-sync` scope onto the card's staged form. */
export class GitSyncCardController {
  private readonly store: SnapshotStore<GitSyncCardState>
  private readonly drafts = new Map<string, boolean | string | number>()
  private saving = false
  private failed = false

  /** @param scope - the bound settings scope for the `git-sync` namespace. */
  constructor(private readonly scope: SettingsScope<GitSyncSettings>) {
    this.store = createSnapshotStore(this.projection())
    this.scope.subscribe(() => { this.publish() })
  }

  /** Build the face the card's slot registration injects. */
  inject(): GitSyncCardFace {
    return {
      hooks: { gitSyncCard: this.store },
      edit: (field, value) => {
        this.drafts.set(field, value)
        this.failed = false
        this.publish()
      },
      save: () => { void this.save() },
      discard: () => {
        this.drafts.clear()
        this.failed = false
        this.publish()
      },
      login: () => { void this.scope.set('loginRequest', Date.now()) },
      refreshStatus: () => { void this.scope.set('statusRequest', Date.now()) },
    }
  }

  private sectionValue(field: string): unknown {
    const value = this.scope.getSnapshot().value as Record<string, unknown> | undefined
    return value?.[field]
  }

  private userHas(field: string): boolean {
    const user = this.scope.getSnapshot().user as Record<string, unknown> | undefined
    return user !== undefined && Object.hasOwn(user, field)
  }

  private fieldState(field: string): GitSyncFieldState {
    const draft = this.drafts.get(field)
    if (draft !== undefined) return { value: draft, overridden: true }
    const stored = this.sectionValue(field)
    const value = typeof stored === 'boolean' || typeof stored === 'number'
      ? stored
      : (typeof stored === 'string' ? stored : '')
    return { value, overridden: this.userHas(field) }
  }

  private projection(): GitSyncCardState {
    const snap = this.scope.getSnapshot()
    const storedStatus = this.sectionValue('authStatus')
    return {
      available: snap.status === 'ready',
      writable: snap.writable,
      dirty: this.drafts.size > 0,
      saving: this.saving,
      failed: this.failed,
      authStatus: typeof storedStatus === 'string' ? storedStatus : 'unknown',
      enabled: this.fieldState('enabled'),
      remoteUrl: this.fieldState('remoteUrl'),
      branch: this.fieldState('branch'),
      intervalMinutes: this.fieldState('intervalMinutes'),
      autoCreateRepo: this.fieldState('autoCreateRepo'),
    }
  }

  private publish(): void {
    this.store.set(this.projection())
  }

  private async save(): Promise<void> {
    if (this.drafts.size === 0 || this.saving) return
    this.saving = true
    this.failed = false
    this.publish()
    try {
      for (const [field, value] of this.drafts) {
        await this.scope.set(field, value)
      }
      this.drafts.clear()
    } catch {
      this.failed = true
    } finally {
      this.saving = false
      this.publish()
    }
  }
}
